// Candidate generated by tools/s81_ph/capture_split.py; original parent remains reference.
`timescale 1ns/1ps
// dsfd_sp_capture_c, CLUSTER form (el1013 S81 capture, 2026-10-13): the die master dsfd_sp_capture_c as a ref_tile
// cluster with NO logic and NO clock tree of its own: wires between hard children and one clock ENTRY per child.
//   dsfd_capt_ctl (1), dsfd_capt_g2 (8), dsfd_capt_x (8)   the CLOSED M5 leaves (NR 16, LD 4, NT 8, KST 1)
//   the KST = 1 station on the ctl <-> group buses           CLOSED die relay masters (one register stage each):
//       W half (groups 0..3): k 99 b = dsfd_rly_68_EW + dsfd_rly_54_EW, status 2 b = dsfd_rly_2_WE
//       E half (groups 4..7): k 99 b = 2 x dsfd_rly_63_WE,              status 2 b = dsfd_rly_2_EW
//       the status word ctl -> the tile left of the control tile (64 b) = dsfd_rly_68_EW
//   dsfd_capt_cd                                             the fld DONE word (16 serial flops), a NEW small leaf
//   dsfd_rly_15_SN                                           t_cd: one serial register stage up the 475 um from the
//                                                            DONE leaf (under the control tile) to the N face
// The first cluster (3fdc48de9) kept the 872 station flops and the DONE word as flat cluster flops under one
// clock pin at the NE corner: its balanced spine measured TT insertion 1,222 ps max, spread 226 ps, boundary mean
// ~1,029 ps (2,102 buffers for 889 sinks over 1.7 mm).  Here every child has its OWN clock entry pin on the cluster
// face next to it (ck_g / ck_x / ck_c / ck_ka / ck_kb / ck_sb / ck_sn, ckv_x / ckv_d / ckv_r): the die delivers the clock at each pin at phi - R of
// that child (R = the child's routed insertion: g2 208 ps, x 269, ctl 90, relays 32..62, die clock delivery rule
// 10-13), so the cluster adds a wire and no tree.
// Ports and behaviour are those of ctrl_c/dsfd_sp_capture_c.sv built with S81PH_CAP_SAFE (dsfd_sp_capture CORE 3 =
// ot_s81ph_cap_t SAFE 1, KST 1) and LD 4, except: t_cd is one serial cycle later (the relay), and the relays clear
// to 0 under rst (the reference station has no reset: equal from the first clock after reset).
// tools/s81_ph/capc_bench.sh runs the two in lockstep (t_vm every cycle, t_cd against the reference one cycle
// earlier) under the gather -> capture golden bench.  Unused relay inputs repeat used bits (no tie cells).
// Mutants: S81PH_CAPC_MUT_KSWAP (every group takes its neighbour's constant bus), S81PH_CAPCD_MUT_NOTOG (dsfd_capt_cd).
module dsfd_sp_capture_split_candidate (
    input wire [7:0] ck_g,                   // clock entry of dsfd_capt_g2 [g]
    input wire [15:0] ck_x,                   // clock entry of dsfd_capt_x [g] (stream side)
    input wire       ck_c,                   // clock entry of dsfd_capt_ctl
    input wire [7:0] ck_ka, ck_kb, ck_sb,    // separate entry for each hardened station relay
    input wire       ck_sn,                 // status-word relay entry
    input wire [0:0] rst,
    input wire ck_status, ckv_status,
    input wire [15:0] ckv_x,                  // serial clock entry of dsfd_capt_x [g]
    input wire       ckv_d,                  // serial clock entry of dsfd_capt_cd (S face, under the control tile)
    input wire       ckv_r,                  // serial clock entry of the t_cd relay (N face)
    input wire [0:0] rsv,
    input wire [6946:0] f_gather,
    output wire [13375:0] t_vm,
    output wire [11:0] t_cd
);
    localparam integer NT = 8, KB = 99;      // KB = `CAPT_KB of ot_s81ph_cap_tile.sv
    wire [NT*KB-1:0] k_c, kd; wire [NT*2-1:0] st, sd; wire [63:0] sn_c, nd;
    wire [63:0] stw;
    dsfd_capt_ctl u_ctl (.ck(ck_c), .rst(rst), .f_ctl(f_gather[6946:6784]), .t_k(k_c), .f_sb(sd), .t_sn(sn_c));
`ifdef S81PH_CAPC_MUT_KSWAP
    wire [NT*KB-1:0] k_w = {k_c[KB-1:0], k_c[NT*KB-1:KB]};   // mutant: every group takes its neighbour's constant bus
`else
    wire [NT*KB-1:0] k_w = k_c;
`endif
    dsfd_capt_rly_64_EW u_sn (.ck(ck_sn), .rs(rst[0]), .i(sn_c), .o(nd));
    genvar g;
    generate for (g = 0; g < NT; g = g + 1) begin : g_t
        wire [16*52-1:0] w;
        
        wire [KB-1:0] kg = k_w[KB * g +: KB];

        if (g < NT / 2) begin : g_w                      // W half: ctl -> group runs E -> W
            wire [67:0] oa; wire [30:0] ob;
            dsfd_rly_68_EW u_ka (.ck(ck_ka[g]), .rs(rst[0]), .i(kg[67:0]), .o(oa));
            dsfd_capt_rly_31_EW u_kb (.ck(ck_kb[g]), .rs(rst[0]), .i(kg[98:68]), .o(ob));
            dsfd_rly_2_WE  u_sb (.ck(ck_sb[g]), .rs(rst[0]), .i(st[2 * g +: 2]), .o(sd[2 * g +: 2]));
            assign kd[KB * g +: KB] = {ob[30:0], oa};
        end else begin : g_e                             // E half: ctl -> group runs W -> E
            wire [62:0] oa; wire [35:0] ob;
            dsfd_rly_63_WE u_ka (.ck(ck_ka[g]), .rs(rst[0]), .i(kg[62:0]), .o(oa));
            dsfd_capt_rly_36_WE u_kb (.ck(ck_kb[g]), .rs(rst[0]), .i(kg[98:63]), .o(ob));
            dsfd_rly_2_EW  u_sb (.ck(ck_sb[g]), .rs(rst[0]), .i(st[2 * g +: 2]), .o(sd[2 * g +: 2]));
            assign kd[KB * g +: KB] = {ob[35:0], oa};
        end
        wire [1:0] ho_half;
        dsfd_capt_g2_dualho u_g (.ck(ck_g[g]), .rst(rst), .f_row(f_gather[53 * 16 * g +: 53 * 16]), .f_k(kd[KB * g +: KB]),
            .t_w(w), .f_ho(ho_half), .t_sb(st[2 * g +: 2]));

        dsfd_capt_x8_data_e u_x0 (.ck(ck_x[2*g]), .rst(rst), .ckv(ckv_x[2*g]), .rsv(rsv),
            .f_w(w[415:0]), .t_vm(t_vm[1664*g +: 832]), .t_ho(ho_half[0]));
        dsfd_capt_x8_data_w u_x1 (.ck(ck_x[2*g+1]), .rst(rst), .ckv(ckv_x[2*g+1]), .rsv(rsv),
            .f_w(w[831:416]), .t_vm(t_vm[1664*g+832 +: 832]), .t_ho(ho_half[1]));

    end endgenerate
    dsfd_capt_status_dual u_status (.ck(ck_status), .rst(rst), .ckv(ckv_status), .rsv(rsv), .f_sn(nd), .t_st(stw)); //   // the tile left of the control tile
    assign t_vm[13375:13312] = stw;
    wire [11:0] cd;
    dsfd_capt_cd u_cd (.ckv(ckv_d), .rsv(rsv[0]), .f_st(stw[13:0]), .t_cd(cd));
    dsfd_capt_rly_12_SN u_cr (.ck(ckv_r), .rs(rsv[0]), .i(cd), .o(t_cd));
endmodule
